<?php $pageTitle='Clientes'; ?><section class="page-head"><div><p class="eyebrow">Administración</p><h1>Clientes registrados</h1><p class="muted">Gestiona las cuentas desde este panel.</p></div></section><div class="panel"><div class="panel-title"><h2>Agregar cliente</h2></div><form class="form-grid" method="post" action="index.php?url=admin/save"><input type="hidden" name="csrf" value="<?=$csrf?>"><label>Nombre<input name="name" required></label><label>Correo<input type="email" name="email" required></label><label>Contraseña inicial<input name="password" value="Cliente123*" required></label><label>Rol<select name="role"><option value="user">Cliente</option><option value="admin">Administrador</option></select></label><button class="btn primary">Agregar cliente</button></form></div><div class="panel table-panel"><div class="panel-title"><h2>Usuarios</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nombre</th><th>Correo</th><th>Rol</th><th>Registro</th><th>Acciones</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td>#<?=$u['id']?></td><td><?=htmlspecialchars($u['name'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><span class="badge role"><?=htmlspecialchars($u['role'])?></span></td><td><?=date('d/m/Y',strtotime($u['created_at']))?></td><td><button class="btn tiny" onclick="toggleModal('user-<?=$u['id']?>')">Editar</button><?php if($u['id']!==Auth::user()['id']): ?><form class="inline" method="post" action="index.php?url=admin/delete" onsubmit="return confirm('¿Eliminar cliente?')"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn tiny danger">Eliminar</button></form><?php endif; ?></td></tr><div id="user-<?=$u['id']?>" class="modal"><div class="modal-box"><button onclick="toggleModal('user-<?=$u['id']?>')" class="close">×</button><h2>Editar cliente</h2><form class="form-grid" method="post" action="index.php?url=admin/save"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$u['id']?>"><label>Nombre<input name="name" value="<?=htmlspecialchars($u['name'])?>"></label><label>Correo<input name="email" value="<?=htmlspecialchars($u['email'])?>"></label><label>Rol<select name="role"><option value="user" <?=$u['role']==='user'?'selected':''?>>Cliente</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Administrador</option></select></label><button class="btn primary">Guardar</button></form></div></div><?php endforeach; ?></tbody></table></div></div>